import { Fragment } from "react";
import Link from "next/link";
import type { GalleryItem, Img, Project, ProjectCard, ProjectStat } from "@/lib/types";
import { cn } from "@/lib/utils";
import { GiantHeading, Label } from "@/components/ui/Headings";
import { CoverMedia } from "@/components/media/CoverMedia";
import { FlowVideo } from "@/components/media/FlowVideo";
import { Media } from "@/components/ui/Media";
import { LoadAhead } from "@/components/media/LoadAhead";
import { ExternalLink } from "@/components/ui/Icons";
import { ProjectBigCard } from "@/components/work/ProjectBigCard";

/** The site’s host name for a link label, e.g. surgohealth.com. */
function displayUrl(url: string) {
  try {
    return new URL(url).hostname.replace(/^www\./, "");
  } catch {
    return url;
  }
}

/** Where a narrow phone has to wrap an address, it breaks before the ending ("cabotsolutions" / ".com"), never inside it. */
function breakBeforeEnding(host: string) {
  const dot = host.lastIndexOf(".");
  return dot > 0 ? (
    <>
      {host.slice(0, dot)}
      <wbr />
      {host.slice(dot)}
    </>
  ) : (
    host
  );
}

/**
 * The work images: the gallery, or for projects without one, the card
 * mockup and the cover. The first is the big image under the name.
 */
function workImages(project: Project): GalleryItem[] {
  if (project.gallery.length) return project.gallery;
  return [project.cardImage, project.cover]
    .filter((img, i, all): img is Img => Boolean(img?.url) && all.findIndex((x) => x?.url === img?.url) === i)
    .map((img, i) => ({ ...img, _key: `fallback${i}`, size: "full" as const }));
}

/** Half-width images sit in pairs; one without a partner goes full width, uncropped. */
function pairHalves(items: GalleryItem[]): GalleryItem[] {
  const out = [...items];
  for (let i = 0; i < out.length; i++) {
    if (out[i].size !== "half") continue;
    if (out[i + 1]?.size === "half") i++;
    else out[i] = { ...out[i], size: "original" };
  }
  return out;
}

/** Case-study Results are hidden for now; set to true to show them again. */
const SHOW_RESULTS = false;

/** Results as big numbers on dark cards. */
function Stats({ stats }: { stats: ProjectStat[] }) {
  const cols = stats.length >= 4 ? "xl:grid-cols-4" : stats.length === 3 ? "md:grid-cols-3" : "";
  return (
    <div className="px-gutter">
      <Label className="mb-[clamp(20px,calc(1.3vw+15px),40px)]">Results</Label>
      <ul className={cn("grid grid-cols-2 gap-gap", cols)}>
        {stats.map((s) => (
          <li
            key={s._key ?? s.label}
            data-reveal
            className={cn(
              "on-dark flex min-h-[clamp(150px,calc(8vw+120px),320px)] flex-col justify-end rounded-card bg-coal p-[clamp(18px,calc(1.9vw+11px),48px)] text-white",
              stats.length === 1 && "col-span-2 md:col-span-1",
            )}
          >
            <span className="text-[length:clamp(40px,calc(3.4vw+28px),112px)] leading-[0.9] font-bold tracking-[-0.045em] tabular-nums">
              {s.value}
            </span>
            <span className="mt-[clamp(10px,1vw,20px)] text-base text-white/70">{s.label}</span>
          </li>
        ))}
      </ul>
    </div>
  );
}

/**
 * A case study in the design system: the name in giant type with its line,
 * one big work image, a few facts beside a short summary, results, then the
 * rest of the work as big image cards and the next two projects.
 *
 * Shared by the full page and the full-screen pop-up. In the pop-up the
 * project cards replace the current entry, so Back still closes it.
 */
export function ProjectDetail({
  project,
  more = [],
  inModal = false,
  titleId,
}: {
  project: Project;
  /** The projects after this one, shown as big cards at the end. */
  more?: ProjectCard[];
  inModal?: boolean;
  /** Id on the name, for the pop-up’s aria-labelledby. */
  titleId?: string;
}) {
  const [hero, ...others] = workImages(project);
  const rest = pairHalves(others);
  // Story blocks spread through the wide images: one after every four or five.
  const every = Math.min(5, Math.max(4, Math.round(rest.length / (project.story.length + 1))));
  const stats: ProjectStat[] = project.stats.length
    ? project.stats
    : project.result?.number && project.result.label
      ? [{ value: project.result.number, label: project.result.label }]
      : [];

  type Fact = { label: string; value: React.ReactNode };
  const client = project.client && project.client !== project.name ? project.client : null;
  const facts = (
    [
      client ? { label: "Client", value: client } : null,
      project.location ? { label: "Location", value: project.location } : null,
      project.year ? { label: "Year", value: project.year } : null,
      project.services.length
        ? {
            label: "Services",
            value: (
              <ul className="flex flex-col gap-1">
                {project.services.map((s) => (
                  <li key={s.slug}>
                    <Link href={`/services/${s.slug}`} className="link-underline">
                      {s.name}
                    </Link>
                  </li>
                ))}
              </ul>
            ),
          }
        : null,
      project.liveUrl
        ? {
            label: "Website",
            value: (
              <a href={project.liveUrl} target="_blank" rel="noopener noreferrer" className="group inline-flex max-w-full items-center gap-2">
                {/* A long address may break onto two lines on the narrowest phones rather than push the page sideways. */}
                <span className="link-underline min-w-0 [overflow-wrap:break-word]">{breakBeforeEnding(displayUrl(project.liveUrl))}</span>
                <ExternalLink className="size-[1.1em] shrink-0 transition-transform duration-300 group-hover:-translate-y-0.5 group-hover:translate-x-0.5" />
                <span className="sr-only">(opens in a new tab)</span>
              </a>
            ),
          }
        : null,
    ] as (Fact | null)[]
  ).filter((f): f is Fact => Boolean(f));
  // Section headings sit one level under the project's title (h1 on the page, h2 in the pop-up).
  const Section = inModal ? "h3" : "h2";
  const BlockHeading = inModal ? "h4" : "h3";

  return (
    <article>
      {/* 1. Name, line and the first work image */}
      <header
        className={cn(
          "pb-[clamp(40px,calc(2.3vw+31.4px),76px)]",
          inModal ? "pt-[clamp(32px,calc(2vw+24px),64px)]" : "pt-[clamp(40px,calc(1.57vw+34px),64px)]",
        )}
      >
        <div id={titleId}>
          <GiantHeading
            as={inModal ? "h2" : "h1"}
            labelStyle="pill"
            label={project.industry || project.services.map((s) => s.shortName).join(" · ") || null}
            heading={project.name}
            text={project.tagline}
          />
        </div>
        {hero && (
          <figure className="mx-gutter mt-[clamp(40px,calc(2.88vw+29.2px),92px)] overflow-hidden rounded-card bg-night">
            {/* Square on phones and 16:9 wider up; uncropped, the image's own shape (or its phone version on phones). */}
            <div
              className={cn(
                "relative",
                hero.size !== "original"
                  ? "aspect-square sm:aspect-video"
                  : hero.phone?.url
                    ? "aspect-square sm:aspect-[var(--ratio)]"
                    : "aspect-[var(--ratio)]",
              )}
              style={hero.size === "original" ? ({ "--ratio": `${hero.width} / ${hero.height}` } as React.CSSProperties) : undefined}
            >
              <CoverMedia
                image={hero}
                phone={hero.phone}
                video={project.coverVideo}
                priority
                sizes="(min-width: 1440px) 1440px, 100vw"
              />
            </div>
            {hero.caption && <figcaption className="sr-only">{hero.caption}</figcaption>}
          </figure>
        )}

      </header>

      {/* 2. A few facts beside the summary */}
      <section className="px-gutter">
        <div className="rule-dotted" />
        <div className="grid gap-[clamp(32px,2.6vw,48px)] py-[clamp(32px,2.9vw,56px)] lg:grid-cols-[minmax(0,4fr)_minmax(0,8fr)] lg:gap-x-gap">
          <dl className="grid grid-cols-2 content-start gap-x-gap gap-y-[clamp(20px,1.6vw,32px)]">
            {facts.map((f) => (
              <div key={f.label} className="min-w-0">
                <dt className="text-small text-mute">{f.label}</dt>
                <dd className="mt-2 text-row [overflow-wrap:break-word]">{f.value}</dd>
              </div>
            ))}
          </dl>
          <p className="max-w-[32ch] text-[length:clamp(22px,calc(0.84vw+18.8px),36px)] leading-[1.25] tracking-[-0.015em] text-pretty">
            {project.summary}
          </p>
        </div>
        <div className="rule-dotted" />
      </section>

      {/* 3. Results */}
      {SHOW_RESULTS && stats.length > 0 && (
        <section className="mt-section">
          <Stats stats={stats} />
        </section>
      )}

      {/* 4. The screen-flow video under its title. The title is never hidden by the
             scroll reveal, so it shows in the pop-up on every browser. */}
      {project.flow?.video?.url && (
        <section className="mt-section px-gutter">
          <div className="mb-[clamp(24px,2.4vw,48px)] grid gap-y-3 md:grid-cols-[minmax(0,4fr)_minmax(0,8fr)] md:gap-x-gap">
            <Section className="text-small text-mute">In motion</Section>
            <p className="max-w-[40ch] text-[length:clamp(22px,calc(0.84vw+18.8px),36px)] leading-[1.25] tracking-[-0.015em] text-pretty">
              {project.flow.heading || `${project.name}, screen by screen.`}
            </p>
          </div>
          <FlowVideo flow={project.flow} label={`A walkthrough of ${project.name}, screen by screen`} />
        </section>
      )}

      {/* 5. The rest of the work, as big image cards with the same margins and
             gaps as the site's other cards: halves at their own proportions,
             one per row on phones and two per row from tablets up; a Full width
             image spans the row at 16:9 from tablets up, and an uncropped one at
             its own proportions. An image with a phone version shows that one,
             square, on phones and itself full width from tablets up, and the
             story's short blocks sit between them, one after every four or five. An image
             with a heading starts a new group under that heading. */}
      {rest.length > 0 && (
        <section id={`gallery-${inModal ? "pop" : "page"}-${project.slug}`} className="mt-section">
          <div className="mb-[clamp(24px,2.4vw,48px)] grid gap-y-3 px-gutter md:grid-cols-[minmax(0,4fr)_minmax(0,8fr)] md:gap-x-gap">
            <Section className="text-small text-mute">The work</Section>
            <p className="max-w-[40ch] text-[length:clamp(22px,calc(0.84vw+18.8px),36px)] leading-[1.25] tracking-[-0.015em] text-pretty">
              More from {project.name}, up close.
            </p>
          </div>
          {/* Images start loading about two screens before they're reached. */}
          <LoadAhead target={`gallery-${inModal ? "pop" : "page"}-${project.slug}`} />
          <ul className="grid grid-cols-2 gap-gap px-gutter">
            {rest.map((img, i) => {
              const wide = Boolean(img.phone?.url);
              const block = wide && (i + 1) % every === 0 && i + 1 < rest.length ? project.story[(i + 1) / every - 1] : undefined;
              return (
                <Fragment key={img._key}>
                  {img.heading && (
                    <li className="col-span-2 pt-[clamp(28px,3.4vw,72px)] first:pt-0">
                      <BlockHeading className="text-[length:clamp(26px,calc(1.2vw+21.4px),48px)] font-medium leading-[1.1] tracking-[-0.02em]">
                        {img.heading}
                      </BlockHeading>
                    </li>
                  )}
              <li className={img.size === "half" && !wide ? "col-span-2 md:col-span-1" : "col-span-2"}>
                <figure
                  className={cn(
                    "relative overflow-hidden rounded-card bg-night",
                    wide && "aspect-square md:aspect-[var(--ratio)]",
                    !wide && img.size === "half" && "aspect-square",
                    !wide && img.size === "full" && "aspect-square md:aspect-video",
                  )}
                  style={
                    wide
                      ? ({ "--ratio": `${img.width} / ${img.height}` } as React.CSSProperties)
                      : img.size !== "full" && img.width && img.height
                        ? { aspectRatio: `${img.width} / ${img.height}` }
                        : undefined
                  }
                >
                  <Media
                    image={img}
                    phone={img.phone}
                    phoneBelow={768}
                    lowPriority
                    sizes={img.size === "half" && !wide ? "(min-width: 768px) 50vw, 100vw" : "100vw"}
                  />
                  {img.caption && (
                    <figcaption className="on-dark absolute inset-x-0 bottom-0 bg-gradient-to-t from-black/70 to-transparent px-[clamp(16px,2.4vw,46px)] pt-16 pb-[clamp(16px,2.4vw,40px)] text-base text-white">
                      {img.caption}
                    </figcaption>
                  )}
                </figure>
              </li>
                  {block && (
                    <li data-reveal className="col-span-2 grid gap-y-3 py-[clamp(28px,4vw,80px)] md:grid-cols-[minmax(0,4fr)_minmax(0,8fr)] md:gap-x-gap">
                      <BlockHeading className="text-small text-mute">{block.title}</BlockHeading>
                      <p className="max-w-[40ch] text-[length:clamp(22px,calc(0.84vw+18.8px),36px)] leading-[1.25] tracking-[-0.015em] text-pretty">
                        {block.text}
                      </p>
                    </li>
                  )}
                </Fragment>
              );
            })}
          </ul>
        </section>
      )}

      {/* 6. Next projects */}
      {more.length > 0 && (
        <section className="mt-section px-gutter">
          <Section className="mb-[clamp(24px,calc(1.7vw+17.6px),50px)] text-h2 font-medium">Next projects</Section>
          <ul className="@container grid grid-cols-1 gap-gap lg:grid-cols-2">
            {more.map((p) => (
              <li key={p._id}>
                <ProjectBigCard project={p} titleAs={inModal ? "h4" : "h3"} replace={inModal} />
              </li>
            ))}
          </ul>
        </section>
      )}
    </article>
  );
}
